using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BEOAudit {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Vector3 V(JToken p)=>new Vector3((float)p[0],(float)p[1],(float)p[2]);
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_")).transform;var old=JArray.Parse(File.ReadAllText(R+"/SourceAssets/B4_ExperimentOperations/scene_before.json"));var issues=new List<string>();int checkedCount=0;
 foreach(var o in old){GlobalObjectId.TryParse((string)o["id"],out var id);var t=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id) as Transform;if(!t){issues.Add("Missing old "+o["name"]);continue;}if(Vector3.Distance(t.position,V(o["position"]))>.0001f||Quaternion.Angle(t.rotation,Quaternion.Euler(V(o["rotation"])))>.05f||Vector3.Distance(t.localScale,V(o["scale"]))>.0001f||t.gameObject.activeSelf!=(bool)o["active"])issues.Add("Old transform changed "+t.name);checkedCount++;}
 var plan=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B4_ExperimentOperations/layout.json"));int guideInside=0;foreach(var mf in root.Find("B4_FloorLayout/B4_CorridorGuides").GetComponentsInChildren<MeshFilter>())foreach(var v in mf.sharedMesh.vertices){var p=mf.transform.TransformPoint(v);foreach(var r in plan["rooms"]){float dx=p.x-(float)r["x"],dz=p.z+(float)r["v"];if(dx*dx+dz*dz<Mathf.Pow((float)r["r"]+.1f,2))guideInside++;}}
 var rr=root.GetComponentsInChildren<Renderer>();int missing=rr.Sum(r=>r.sharedMaterials.Count(m=>!m||!m.shader));if(missing>0||guideInside>0)issues.Add("Material/guidance error");long tri=root.GetComponentsInChildren<MeshFilter>().Sum(f=>(long)f.sharedMesh.triangles.Length/3);var added=root.Find("B4_ExperimentEquipment");foreach(var l in added.GetComponentsInChildren<Light>())if(Vector3.Angle(l.transform.forward,-l.transform.parent.up)>.05f)issues.Add("Light alignment "+l.transform.parent.name);
 var result=new{scene=s.path,oldChecked=checkedCount,missing,guideInside,renderers=rr.Length,colliders=root.GetComponentsInChildren<Collider>().Length,lights=root.GetComponentsInChildren<Light>().Length,triangles=tri,addedAssets=plan["newPlacements"].Count(),issues};File.WriteAllText(R+"/Docs/검수/2026-11-08_B4_ExperimentOperations/audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
